# Bit-exact comparison of the Nim VP8L decoder with the ORIGINAL ThorVG libwebp copy.
#   . env.ps1 ; powershell -File tests\parity\webp_ll_compare.ps1 [-Mutants 200] [-Rebuild]
# Inputs: tests\data\webp\gen\*.webp (generated by mkwebp_cases.nim) and every real file of
# tests\data\webp whose first chunk is VP8L. Each file is decoded in BGRA and RGBA mode by
# build\cpp\cpp_webp_dump_ll.exe (whole RIFF file, like tvgWebpLoader.cpp) and by
# build\nim_webp_dump_ll.exe; the dumps (w, h, premultiplied words) must be identical.
# -Mutants N additionally decodes N corrupted copies of generated files (bit flips, or
# truncation with consistent RIFF/chunk sizes): both decoders must agree on accept/reject and
# on the pixels. Always run from the project root. Exit code 0 = all identical.
param(
  [int]$Mutants = 200,
  [switch]$Rebuild,
  [string]$Scratch = 'C:\Temp\opencode\webpll'
)
[Environment]::CurrentDirectory = (Get-Location).Path
$ErrorActionPreference = 'Stop'
$scripts = 'C:\Users\C08937\.config\opencode\skills\nim-toolchain-win\scripts'
$cppExe = 'build\cpp\cpp_webp_dump_ll.exe'
$nimExe = 'build\nim_webp_dump_ll.exe'
New-Item -ItemType Directory -Force $Scratch | Out-Null

if ($Rebuild -or -not (Test-Path $cppExe)) {
  $tvg = 'upstream/thorvg'
  $st = "$tvg/src/modules/webp/static"
  $flags = @('-std=c++14', '-O2', '-DNDEBUG', '-ffp-contract=off', '-fno-math-errno', '-Wno-unknown-pragmas', '-w',
    '-DTVG_STATIC', '-DNOMINMAX', '-Ibuild/cpp/include', "-I$tvg/inc", "-I$tvg/src/common", "-I$tvg/src/renderer",
    "-I$tvg/src/modules", "-I$st")
  $srcs = @(Get-ChildItem "$st\dec", "$st\dsp", "$st\utils" -Filter *.cpp | ForEach-Object { $_.FullName }) + @((Resolve-Path 'tests\parity\cpp_webp_dump_ll.cpp').Path)
  New-Item -ItemType Directory -Force build\cpp\webpll | Out-Null
  $objs = @()
  foreach ($s in $srcs) {
    $o = 'build\cpp\webpll\' + [IO.Path]::GetFileNameWithoutExtension($s) + '_' + ([IO.Path]::GetFileName((Split-Path $s -Parent))) + '.o'
    & g++ @flags -c $s -o $o
    if ($LASTEXITCODE -ne 0) { throw "g++ failed on $s" }
    $objs += $o
  }
  & g++ @objs -o $cppExe
  if ($LASTEXITCODE -ne 0) { throw 'link failed' }
}
& "$scripts\nimc.ps1" -Src tests\parity\nim_webp_dump_ll.nim -Mode release -Strict -Out $nimExe | Out-Null
if ($LASTEXITCODE -ne 0) { throw 'nim dump build failed' }

function Test-Lossless([string]$path) {
  $b = [IO.File]::ReadAllBytes($path)
  return ($b.Length -gt 20 -and [Text.Encoding]::ASCII.GetString($b, 12, 4) -eq 'VP8L')
}

# returns "ok" or a message describing the first mismatch
function Compare-One([string]$file, [string]$mode) {
  $c = Join-Path $Scratch 'c.bin'
  $n = Join-Path $Scratch 'n.bin'
  Remove-Item $c, $n -ErrorAction SilentlyContinue
  & $cppExe $file $c $mode | Out-Null
  & $nimExe $file $n $mode | Out-Null
  if (-not (Test-Path $c) -or -not (Test-Path $n)) { return 'dump missing' }
  $a = [IO.File]::ReadAllBytes($c)
  $bb = [IO.File]::ReadAllBytes($n)
  if ($a.Length -ne $bb.Length) { return "size differs: C++ $($a.Length) Nim $($bb.Length)" }
  for ($i = 0; $i -lt $a.Length; $i++) {
    if ($a[$i] -ne $bb[$i]) { return "byte $i differs: C++ $($a[$i]) Nim $($bb[$i])" }
  }
  return 'ok'
}

$files = @(Get-ChildItem tests\data\webp\gen -Filter *.webp | ForEach-Object { $_.FullName })
$files += @(Get-ChildItem tests\data\webp -Filter *.webp | Where-Object { Test-Lossless $_.FullName } | ForEach-Object { $_.FullName })
$fail = 0
$count = 0
foreach ($f in $files) {
  foreach ($mode in 'bgra', 'rgba') {
    $r = Compare-One $f $mode
    $count++
    if ($r -ne 'ok') { $fail++; Write-Host "FAIL $mode $(Split-Path $f -Leaf): $r" }
  }
}
Write-Host "files: $($files.Count) comparisons: $count failures: $fail"

if ($Mutants -gt 0) {
  $rng = New-Object System.Random 4242
  $gen = @(Get-ChildItem tests\data\webp\gen -Filter *_33x17.webp | ForEach-Object { $_.FullName })
  $gen += @(Get-ChildItem tests\data\webp\gen -Filter *_5x7.webp | ForEach-Object { $_.FullName })
  $mfail = 0
  $accepted = 0
  for ($k = 0; $k -lt $Mutants; $k++) {
    $b = [IO.File]::ReadAllBytes($gen[$rng.Next($gen.Count)])
    if ($k % 3 -eq 0) {
      $len = 21 + $rng.Next($b.Length - 21)
      $b = $b[0..($len - 1)]
      $riff = $len - 8; $chunk = $len - 20
      for ($i = 0; $i -lt 4; $i++) { $b[4 + $i] = ($riff -shr (8 * $i)) -band 255; $b[16 + $i] = ($chunk -shr (8 * $i)) -band 255 }
    } else {
      for ($j = 0; $j -le $rng.Next(3); $j++) { $b[20 + $rng.Next($b.Length - 20)] = $rng.Next(256) }
    }
    $mf = Join-Path $Scratch 'mut.webp'
    [IO.File]::WriteAllBytes($mf, $b)
    $r = Compare-One $mf 'bgra'
    $dump = [IO.File]::ReadAllBytes((Join-Path $Scratch 'c.bin'))
    if ($dump.Length -gt 8) { $accepted++ }
    if ($r -ne 'ok') {
      $mfail++
      $keep = Join-Path $Scratch ("mut_fail_$k.webp")
      Copy-Item $mf $keep
      Write-Host "MUTANT FAIL #$k ($keep): $r"
    }
  }
  Write-Host "mutants: $Mutants (decoded by the original: $accepted) failures: $mfail"
  $fail += $mfail
}
if ($fail -eq 0) { Write-Host 'ALL IDENTICAL' } else { Write-Host "$fail MISMATCHES" }
exit ([int]($fail -ne 0))
